create extension if not exists pgcrypto;
create table companies(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table customers(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,name text not null,phone text,email text,created_at timestamptz not null default now());
create table customer_vehicles(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customers(id) on delete cascade,brand text,model text,year int,engine text,version text,plate text,created_at timestamptz not null default now());
create table products(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,sku text not null,name text not null,normalized_name text,category text,brand text,original_code text,description text,active boolean not null default true,created_at timestamptz not null default now(),unique(company_id,sku));
create table product_prices(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,price numeric(12,2) not null,price_type text not null default 'retail',valid_from timestamptz not null default now(),valid_to timestamptz);
create table vehicle_applications(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,vehicle_brand text not null,vehicle_model text not null,year_start int,year_end int,engine text,version text,side text,position text,notes text);
create table conversations(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,customer_id uuid references customers(id),channel text not null default 'web',status text not null default 'open',assigned_to uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table conversation_messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations(id) on delete cascade,sender text not null,content text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table quotes(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id),customer_id uuid references customers(id),status text not null default 'draft',total numeric(12,2) not null default 0,created_at timestamptz not null default now());
create table quote_items(id uuid primary key default gen_random_uuid(),quote_id uuid not null references quotes(id) on delete cascade,product_id uuid not null references products(id),quantity int not null default 1,unit_price numeric(12,2) not null);
create index products_name_idx on products(company_id,normalized_name);
create index applications_vehicle_idx on vehicle_applications(vehicle_brand,vehicle_model,year_start,year_end);
